// DETERMINISTIC extract + positive "real meeting" classifier. Zero LLM.
// Runs after the keyword denylist (Is Real Meeting IF). It:
//   1. Re-derives attendee emails + UNIQUE domains from the ACTUAL Google
//      Calendar attendees array (fixes Relay's empty-domains bug: Relay mapped
//      key "email domains" but read input.emails -> domains were always blank).
//   2. Computes a POSITIVE real-meeting signal that the keyword denylist misses
//      (solo doctor/flight/focus blocks): otherAttendeeCount + hasVideoLink.
//   3. Emits the normalized fields + booleans for the downstream If.
// Convergence-safe: the event arrives on $input; no cross-node $() needed here,
// but we still guard every lookup.
const SELF_EMAIL = 'alex@ahbadvisors.com';
let ev = {};
try { ev = $input.item.json || {}; } catch (e) { ev = {}; }

const attendees = Array.isArray(ev.attendees) ? ev.attendees : [];

// All guest emails (for the Attendee Emails field).
const allEmails = attendees
  .map(a => (a && a.email ? String(a.email).trim() : ''))
  .filter(Boolean);

// "Other" attendees = real humans who are not Alex, not the calendar owner
// (self), and not a resource (room/equipment).
const otherAttendees = attendees.filter(a => {
  if (!a) return false;
  if (a.self === true) return false;
  if (a.resource === true) return false;
  const em = a.email ? String(a.email).trim().toLowerCase() : '';
  if (!em) return false;
  if (em === SELF_EMAIL.toLowerCase()) return false;
  return true;
});
const otherAttendeeCount = otherAttendees.length;

// Unique email domains (deterministic dedup) — the bug Relay never fixed.
const attendeeDomains = [...new Set(
  allEmails
    .map(e => (e.split('@')[1] || '').toLowerCase())
    .filter(Boolean)
)];

// Video / conference link: hangoutLink, then conferenceData entry points,
// then a URL sniffed from location/description.
let meetingLink = ev.hangoutLink || '';
if (!meetingLink && ev.conferenceData && Array.isArray(ev.conferenceData.entryPoints)) {
  const video = ev.conferenceData.entryPoints.find(p => p && p.entryPointType === 'video');
  meetingLink = (video && video.uri) || (ev.conferenceData.entryPoints[0] && ev.conferenceData.entryPoints[0].uri) || '';
}
const VIDEO_RE = /(zoom\.us|meet\.google\.com|teams\.microsoft\.com|teams\.live\.com|webex\.com|whereby\.com|meet\.jit\.si|hangouts\.google\.com)/i;
let sniffedLink = '';
const blob = String((ev.location || '') + ' ' + (ev.description || ''));
const m = blob.match(/https?:\/\/\S+/g);
if (m) { const hit = m.find(u => VIDEO_RE.test(u)); if (hit) sniffedLink = hit.replace(/[)>\].,]+$/, ''); }
if (!meetingLink && sniffedLink) meetingLink = sniffedLink;

const hasVideoLink = Boolean(
  ev.hangoutLink ||
  (ev.conferenceData && ((ev.conferenceData.entryPoints && ev.conferenceData.entryPoints.length) || ev.conferenceData.conferenceId)) ||
  meetingLink ||
  VIDEO_RE.test(blob)
);

// POSITIVE gate: a real meeting has at least one other human OR a video link.
const isRealMeeting = (otherAttendeeCount >= 1) || hasVideoLink;

const startRaw = (ev.start && (ev.start.dateTime || ev.start.date)) || '';
const startDate = startRaw ? String(startRaw).slice(0, 10) : '';
let startMs = 0;
if (startRaw) { const d = new Date(startRaw); if (!isNaN(d.getTime())) startMs = d.getTime(); }
const dueMs = startMs ? startMs - 24 * 60 * 60 * 1000 : 0;

return {
  json: {
    gcalId: ev.id || '',
    gcalLink: ev.htmlLink || '',
    meetingLink,
    title: ev.summary || '(no title)',
    startRaw,
    startDate,
    startMs,
    dueMs,
    attendeeEmails: allEmails.join(', '),
    attendeeDomains: attendeeDomains.join(', '),
    otherAttendeeCount,
    hasVideoLink,
    isRealMeeting
  }
};

// Parse the ClickUp list-task lookup response. Deterministic; no LLM.
// The GET returns { tasks: [...] }. We treat the FIRST match on the gCal ID
// custom field as the existing agenda task (idempotency + reschedule key).
// Convergence-safe: guard the upstream $() ref in try/catch.
let ctx = {};
try { ctx = $('Extract + Classify').item.json || {}; } catch (e) { ctx = {}; }

let resp = {};
try { resp = $input.item.json || {}; } catch (e) { resp = {}; }

let tasks = [];
if (Array.isArray(resp.tasks)) tasks = resp.tasks;
else if (Array.isArray(resp.body && resp.body.tasks)) tasks = resp.body.tasks;

const found = tasks.length > 0;
const existingTaskId = found ? (tasks[0].id || '') : '';

return {
  json: Object.assign({}, ctx, {
    found,
    existingTaskId
  })
};

